const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const today = new Date().toDateString();
const events = $('Get Unreported email_events').all().map(i => { const f = i.json.fields || i.json; return { id: i.json.id || f.id || '', subject: f.subject || '(no subject)', from_name: f.from_name || f.from_email || '', category: f.category || 'other', importance: f.importance || 'low', has_draft: !!f.draft_id, message_id: f.message_id || '' }; }).filter(e => e.id);
const tasks = $('Get Asana Tasks').all().map(i => i.json).filter(t => t && !t.completed).map(t => ({ name: t.name || '(unnamed)', due_on: t.due_on || t.due_at || null, notes: String(t.notes || '').slice(0, 160) }));
const high = events.filter(e => e.importance === 'high');
const replyNeeded = events.filter(e => e.has_draft);
const overdue = tasks.filter(t => t.due_on && t.due_on < new Date().toISOString().slice(0, 10));
let brief = 'Daily Operations Brief — ' + today + '

';
brief += 'Urgent mail (' + high.length + '):
';
brief += high.length ? high.map(e => '  • [' + e.category + '] ' + e.subject + ' — from ' + e.from_name).join('
') : '  (none)';
brief += '

Drafts awaiting review (' + replyNeeded.length + '):
';
brief += replyNeeded.length ? replyNeeded.map(e => '  • ' + e.subject + ' — from ' + e.from_name).join('
') : '  (none)';
brief += '

Open Asana tasks (' + tasks.length + ', overdue ' + overdue.length + '):
';
brief += tasks.length ? tasks.slice(0, 20).map(t => '  • ' + t.name + (t.due_on ? ' (due ' + t.due_on + ')' : '')).join('
') : '  (none)';
if (overdue.length) { brief += '

Overdue:
' + overdue.map(t => '  • ' + t.name + ' (due ' + t.due_on + ')').join('
'); }
return [{ json: { today, brief_text: brief, brief_html: '<pre>' + esc(brief) + '</pre>', event_ids: events.map(e => ({ id: e.id, message_id: e.message_id })), high_count: high.length, reply_count: replyNeeded.length, task_count: tasks.length, overdue_count: overdue.length } }];

const safeAll = name => { try { return $(name).all(); } catch (e) { return []; } };
const b = $('Build Brief').first().json || {};
const sendItems = safeAll('Send Brief');
const sendErr = sendItems.length && sendItems[0].json.error ? String(sendItems[0].json.error) : '';
const marked = safeAll('Mark Reported').filter(i => i.json && i.json.id).length;
return [{ json: {
  date: b.today,
  delivered: !sendErr,
  delivery_error: sendErr,
  items_reported: marked,
  high_count: b.high_count,
  reply_count: b.reply_count,
  task_count: b.task_count,
  overdue_count: b.overdue_count,
  final_status: sendErr ? 'delivery_failed_items_remain_unreported' : (marked ? 'brief_delivered_items_reported' : 'brief_delivered_nothing_to_report')
}}];
